from pathlib import Path
root=Path.cwd(); j=root/'app/src/main/java/com/suhas/multyfideliverybuy'

def read(n): return (j/n).read_text()
def write(n,s): (j/n).write_text(s)

# Version
p=root/'app/build.gradle'; s=p.read_text();
if 'versionCode 147' not in s: raise SystemExit('Expected v1.4.7 base')
p.write_text(s.replace('versionCode 147','versionCode 148').replace("versionName '1.4.7'","versionName '1.4.8'"))

# Parser: Back in Entry Range is its own follow-up signal; duration comes from the already-open campaign.
s=read('UnivestParser.java').replace('enum Type { ENTRY, EXIT }','enum Type { ENTRY, RANGE_ADD, EXIT }')
needle='''        return null;\n    }\n\n    private static boolean isEligibleEntryDuration'''
insert='''        if (containsAny(lower, "idea back in entry range", "back in entry range")) {\n            return new Signal(Type.RANGE_ADD, symbol, text);\n        }\n\n        return null;\n    }\n\n    private static boolean isEligibleEntryDuration'''
if needle not in s: raise SystemExit('Parser insertion point missing')
write('UnivestParser.java',s.replace(needle,insert))

# State: dedupe exact Android notification callbacks, but allow later genuine range alerts.
s=read('UnivestStateStore.java')
s=s.replace('String lastAction = "";\n        long updatedAt', 'String lastAction = "";\n        long lastRangeAddNotificationTime = 0L;\n        long updatedAt')
s=s.replace('j.put("lastAction", lastAction);\n                j.put("updatedAt"', 'j.put("lastAction", lastAction);\n                j.put("lastRangeAddNotificationTime", lastRangeAddNotificationTime);\n                j.put("updatedAt"')
s=s.replace('s.lastAction = j.optString("lastAction", "");\n            s.updatedAt', 's.lastAction = j.optString("lastAction", "");\n            s.lastRangeAddNotificationTime = j.optLong("lastRangeAddNotificationTime", 0L);\n            s.updatedAt')
mark='    static synchronized void releasePendingEntry(Context c, String symbol, String reason) {'
add='''    static boolean canRangeAddPhase(String phase) {\n        return ACTIVE.equals(phase) || WAIT_REENTRY.equals(phase) || FLAT_WAIT_EXIT.equals(phase);\n    }\n\n    static synchronized boolean reserveRangeAdd(Context c, String symbol, long postTime) {\n        if (symbol == null || symbol.trim().isEmpty()) return false;\n        State state=get(c,symbol.trim().toUpperCase());\n        if (state==null || !canRangeAddPhase(state.phase)) return false;\n        long t=postTime>0?postTime:System.currentTimeMillis();\n        if (t<=state.lastRangeAddNotificationTime) return false;\n        state.lastRangeAddNotificationTime=t;\n        state.lastAction="Back in Entry Range ₹5,000 add reserved before BUY dispatch.";\n        put(c,state); return true;\n    }\n\n'''
if mark not in s: raise SystemExit('State insertion point missing')
write('UnivestStateStore.java',s.replace(mark,add+mark))

# Notification listener: serialize range adds through the same Univest buy executor.
s=read('MultyfiNotificationService.java')
mark='''        if (signal.type == UnivestParser.Type.ENTRY) {\n'''
add='''        if (signal.type == UnivestParser.Type.RANGE_ADD) {\n            if (!AppPrefs.isReadyForBuy(getApplicationContext())) {\n                AppPrefs.setUnivestStatus(getApplicationContext(), "UNIVEST BACK-IN-RANGE IGNORED • " + signal.symbol + " • Groww connection readiness is stale."); return;\n            }\n            if (!UnivestStateStore.reserveRangeAdd(getApplicationContext(), signal.symbol, postTime)) {\n                UnivestStateStore.State x=UnivestStateStore.get(getApplicationContext(),signal.symbol);\n                AppPrefs.setUnivestStatus(getApplicationContext(), "UNIVEST BACK-IN-RANGE IGNORED/DUPLICATE • " + signal.symbol + " • current state " + (x==null?"NOT TRACKED":x.phase) + "."); return;\n            }\n            AppPrefs.setUnivestStatus(getApplicationContext(), "UNIVEST BACK IN ENTRY RANGE ACCEPTED • " + signal.symbol + " • additional ₹5,000 CNC DELIVERY BUY starting.");\n            univestBuyExecutor.execute(() -> {\n                UnivestManager.handleRangeAdd(getApplicationContext(),signal,postTime);\n                showLocalStatus("UNIVEST ENTRY RANGE",AppPrefs.getUnivestStatus(getApplicationContext()),true);\n            });\n            return;\n        }\n\n'''
if mark not in s: raise SystemExit('Notification insertion point missing')
write('MultyfiNotificationService.java',s.replace(mark,add+mark,1))

# Strategy: each accepted alert adds one fixed ₹5k CNC market tranche. Price-based -2/-4/-6/-8 averaging stays separate.
s=read('UnivestManager.java').replace('static final int AVERAGE_BUDGET = 5000;','static final int AVERAGE_BUDGET = 5000;\n    static final int RANGE_ADD_BUDGET = 5000;')
mark='    static void handleExit(Context context, UnivestParser.Signal signal, long notificationPostTime) {'
method='''    static void handleRangeAdd(Context context, UnivestParser.Signal signal, long notificationPostTime) {\n        if (signal==null || signal.type!=UnivestParser.Type.RANGE_ADD) return;\n        String symbol=signal.symbol.toUpperCase(Locale.US);\n        UnivestStateStore.State state=UnivestStateStore.get(context,symbol);\n        if (state==null || !UnivestStateStore.canRangeAddPhase(state.phase)) { status(context,"UNIVEST BACK-IN-RANGE IGNORED • "+symbol+" • no open eligible campaign."); return; }\n        InstrumentRepository.Instrument i=InstrumentRepository.resolve(InstrumentRepository.load(context),symbol);\n        if (i==null || !i.buyAllowed) { status(context,"UNIVEST BACK-IN-RANGE BUY SKIPPED • "+symbol+" • NSE CASH instrument unavailable/buy_allowed=0."); return; }\n\n        boolean wasFlat=state.quantity<=0 || UnivestStateStore.WAIT_REENTRY.equals(state.phase) || UnivestStateStore.FLAT_WAIT_EXIT.equals(state.phase);\n        if (wasFlat && state.activeGttId!=null && !state.activeGttId.isEmpty()) {\n            GrowwClient.Result c=cancelTrackedGttSafe(context,state);\n            if (!c.success) { status(context,"UNIVEST BACK-IN-RANGE BUY BLOCKED • "+symbol+" • pending re-entry GTT cancellation unconfirmed • "+c.message); return; }\n            state=UnivestStateStore.get(context,symbol); if(state==null)return;\n        }\n        GrowwClient.ExecutionResult r=GrowwClient.placeUnivestCncMarketBuy(context,symbol,RANGE_ADD_BUDGET,ref("UVB",symbol));\n        long ageMs=r.dispatchAtMillis>0&&notificationPostTime>0?Math.max(0L,r.dispatchAtMillis-notificationPostTime):-1L;\n        if(!r.submitted){state.lastAction="Back in Entry Range ₹5,000 BUY not submitted. "+r.message;UnivestStateStore.put(context,state);status(context,"UNIVEST BACK-IN-RANGE BUY NOT SUBMITTED • "+symbol+age(ageMs)+" • "+r.message);return;}\n        if(!r.filled||r.filledQuantity<=0||!(r.averagePrice>0)){state.phase=UnivestStateStore.ERROR;state.lastAction="Back in Entry Range BUY accepted but fill unconfirmed; paused to avoid duplicate/under-protected quantity. "+r.message;UnivestStateStore.put(context,state);status(context,"UNIVEST BACK-IN-RANGE BUY ACCEPTED — VERIFY FILL • "+symbol+age(ageMs)+" • "+r.message);return;}\n\n        double value=r.averagePrice*r.filledQuantity;\n        if(wasFlat){state.phase=UnivestStateStore.ACTIVE;state.quantity=r.filledQuantity;state.principal=value;state.estimatedBuyCharges=DeliveryNetTarget.buyCharges(value);state.averageLevel=0;state.reentryUsed=true;}\n        else{state.quantity+=r.filledQuantity;state.principal+=value;state.estimatedBuyCharges+=DeliveryNetTarget.buyCharges(value);}\n        GrowwClient.PositionSnapshot pos=GrowwClient.getCncPosition(context,symbol);state.brokerQtyAfterLastFill=pos.success?pos.quantity:-1;\n        state.lastAction="Back in Entry Range ₹5,000 CNC BUY executed • qty +"+r.filledQuantity+" @ avg ₹"+money(r.averagePrice)+age(ageMs);UnivestStateStore.put(context,state);\n        String stop=wasFlat?armProtectiveStop(context,state):refreshProtectiveStopAfterFill(context,state);\n        String avg=UnivestStateStore.ACTIVE.equals(state.phase)?armNextAverage(context,state):"averaging paused";\n        status(context,"UNIVEST BACK IN ENTRY RANGE BUY EXECUTED • "+symbol+" • +₹5,000 tranche • qty +"+r.filledQuantity+" • avg ₹"+money(r.averagePrice)+age(ageMs)+" • total tracked qty "+state.quantity+" • "+stop+" • "+avg);\n    }\n\n'''
if mark not in s: raise SystemExit('Manager insertion point missing')
write('UnivestManager.java',s.replace(mark,method+mark,1))

# UI
s=read('MainActivity.java').replace('v1.4.7  •  DELIVERY FIRST','v1.4.8  •  DELIVERY FIRST').replace('v1.4.7 • Delivery Trade Hub','v1.4.8 • Delivery Trade Hub'); write('MainActivity.java',s)

